practice.solution:
import { readFileSync } from "node:fs";

type Result<T, E> = { ok: true; value: T } | { ok: false; error: E };

export type Settings = { theme: "light" | "dark"; fontSize: number };

function parseJson(text: string): Result<unknown, string> {
  try {
    return { ok: true, value: JSON.parse(text) };
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : String(err) };
  }
}

function isRecord(x: unknown): x is Record<string, unknown> {
  return typeof x === "object" && x !== null && !Array.isArray(x);
}

export function parseSettings(text: string): Settings {
  const settings: Settings = { theme: "light", fontSize: 16 };
  const result = parseJson(text);
  if (!result.ok || !isRecord(result.value)) {
    return settings;
  }
  const data = result.value;
  if (data.theme === "light" || data.theme === "dark") {
    settings.theme = data.theme;
  }
  if (typeof data.fontSize === "number") {
    settings.fontSize = data.fontSize;
  }
  return settings;
}

console.log(JSON.stringify(parseSettings(readFileSync(0, "utf8"))));

steps.body:
A guard answers yes or no. When the data comes from someone else, they also need to know what's wrong and where, so a validator reports every problem with its **path**: the route to the field, written the way you'd reach it in code, like `address.city` or `items[2].qty`.

The pattern has three steps. Narrow the object, read each field through a small helper that checks it, and return the typed value only when nothing failed:

```typescript
function readNumber(value: unknown, path: string, errors: string[]): number {
  if (typeof value === "number") {
    return value;
  }
  errors.push(`${path}: expected a number`);
  return 0;
}
const errors: string[] = [];
readNumber("3", "items[0].qty", errors);
console.log(errors.join("\n")); // items[0].qty: expected a number
```

The `0` that a failed read returns is a placeholder nobody sees: any error means the validator returns `{ ok: false, errors }` instead of the value. For an array, check `Array.isArray`, copy it into an `unknown[]`, and validate each element with its index in the path.

examples.code:
type User = { name: string; age: number; address: { city: string } };
type Validation<T> = { ok: true; value: T } | { ok: false; errors: string[] };

function isRecord(x: unknown): x is Record<string, unknown> {
  return typeof x === "object" && x !== null && !Array.isArray(x);
}

function readString(value: unknown, path: string, errors: string[]): string {
  if (typeof value === "string") {
    return value;
  }
  errors.push(`${path}: expected a string`);
  return "";
}

function readNumber(value: unknown, path: string, errors: string[]): number {
  if (typeof value === "number") {
    return value;
  }
  errors.push(`${path}: expected a number`);
  return 0;
}

function validateUser(x: unknown): Validation<User> {
  if (!isRecord(x)) {
    return { ok: false, errors: ["expected an object"] };
  }
  const errors: string[] = [];
  const name = readString(x.name, "name", errors);
  const age = readNumber(x.age, "age", errors);
  let city = "";
  if (isRecord(x.address)) {
    city = readString(x.address.city, "address.city", errors);
  } else {
    errors.push("address: expected an object");
  }
  if (errors.length > 0) {
    return { ok: false, errors };
  }
  return { ok: true, value: { name, age, address: { city } } };
}

const inputs = [
  '{"name": "Ada", "age": 36, "address": {"city": "London"}}',
  '{"name": "Grace", "age": "85", "address": {"city": null}}',
  '{"age": 54}',
];
for (const text of inputs) {
  const result = validateUser(JSON.parse(text));
  if (result.ok) {
    console.log(`valid: ${result.value.name}, ${result.value.age}, ${result.value.address.city}`);
  } else {
    console.log(`invalid:\n  ${result.errors.join("\n  ")}`);
  }
}

import { readFileSync } from "node:fs";

type Track = { title: string; seconds: number };
type Playlist = { name: string; tracks: Track[] };
type Validation<T> = { ok: true; value: T } | { ok: false; errors: string[] };

function isRecord(x: unknown): x is Record<string, unknown> {
  return typeof x === "object" && x !== null && !Array.isArray(x);
}

function readString(value: unknown, path: string, errors: string[]): string {
  if (typeof value === "string") {
    return value;
  }
  errors.push(`${path}: expected a string`);
  return "";
}

function readNumber(value: unknown, path: string, errors: string[]): number {
  if (typeof value === "number") {
    return value;
  }
  errors.push(`${path}: expected a number`);
  return 0;
}

function validatePlaylist(x: unknown): Validation<Playlist> {
  if (!isRecord(x)) {
    return { ok: false, errors: ["expected an object"] };
  }
  const errors: string[] = [];
  const name = readString(x.name, "name", errors);
  const tracks: Track[] = [];
  if (Array.isArray(x.tracks)) {
    const items: unknown[] = x.tracks;
    for (const [i, item] of items.entries()) {
      const path = `tracks[${i}]`;
      if (isRecord(item)) {
        const title = readString(item.title, `${path}.title`, errors);
        const seconds = readNumber(item.seconds, `${path}.seconds`, errors);
        tracks.push({ title, seconds });
      } else {
        errors.push(`${path}: expected an object`);
      }
    }
  } else {
    errors.push("tracks: expected an array");
  }
  return errors.length > 0 ? { ok: false, errors } : { ok: true, value: { name, tracks } };
}

const result = validatePlaylist(JSON.parse(readFileSync(0, "utf8")));
if (result.ok) {
  console.log(`${result.value.name}: ${result.value.tracks.length} tracks`);
} else {
  console.log(result.errors.join("\n"));
}

import { readFileSync } from "node:fs";

type Address = { line1: string; city: string; postcode: string; country: string };
type Customer = {
  id: string;
  name: string;
  email: string;
  phone: string;
  age: number;
  points: number;
  tags: string[];
  address: Address;
};
type Validation<T> = { ok: true; value: T } | { ok: false; errors: string[] };

function isRecord(x: unknown): x is Record<string, unknown> {
  return typeof x === "object" && x !== null && !Array.isArray(x);
}

function readString(value: unknown, path: string, errors: string[]): string {
  if (typeof value === "string") {
    return value;
  }
  errors.push(`${path}: expected a string`);
  return "";
}

function readNumber(value: unknown, path: string, errors: string[]): number {
  if (typeof value === "number") {
    return value;
  }
  errors.push(`${path}: expected a number`);
  return 0;
}

function validateCustomer(x: unknown): Validation<Customer> {
  if (!isRecord(x)) {
    return { ok: false, errors: ["expected an object"] };
  }
  const errors: string[] = [];
  const id = readString(x.id, "id", errors);
  const name = readString(x.name, "name", errors);
  const email = readString(x.email, "email", errors);
  const phone = readString(x.phone, "phone", errors);
  const age = readNumber(x.age, "age", errors);
  const points = readNumber(x.points, "points", errors);
  const tags: string[] = [];
  if (Array.isArray(x.tags)) {
    const items: unknown[] = x.tags;
    for (const [i, tag] of items.entries()) {
      tags.push(readString(tag, `tags[${i}]`, errors));
    }
  } else {
    errors.push("tags: expected an array");
  }
  const address: Address = { line1: "", city: "", postcode: "", country: "" };
  if (isRecord(x.address)) {
    address.line1 = readString(x.address.line1, "address.line1", errors);
    address.city = readString(x.address.city, "address.city", errors);
    address.postcode = readString(x.address.postcode, "address.postcode", errors);
    address.country = readString(x.address.country, "address.country", errors);
  } else {
    errors.push("address: expected an object");
  }
  if (errors.length > 0) {
    return { ok: false, errors };
  }
  return { ok: true, value: { id, name, email, phone, age, points, tags, address } };
}

const result = validateCustomer(JSON.parse(readFileSync(0, "utf8")));
console.log(result.ok ? `valid: ${result.value.name}` : result.errors.join("\n"));

