type JsonValue =
  | string
  | number
  | boolean
  | null
  | JsonValue[]
  | { [key: string]: JsonValue };

function orderJson(id: string, placedAt: Date, skus: string[]): JsonValue {
  return {
    id,
    placedAt: placedAt.toISOString(),
    skus,
    gift: false,
    note: null,
  };
}

const json = orderJson("ord_1", new Date("2026-10-01T09:00:00Z"), ["MUG-1", "TEA-4"]);
console.log(JSON.stringify(json));

examples.explanation:
`JsonValue` refers to itself, so arrays and objects can nest to any depth, and every value inside them must be JSON too. `orderJson` converts the `Date` with `toISOString()` before it puts it in, so the function type-checks. Leave the conversion out, and it doesn't:

```typescript error
type JsonValue =
  | string
  | number
  | boolean
  | null
  | JsonValue[]
  | { [key: string]: JsonValue };

function orderJson(id: string, placedAt: Date): JsonValue {
  return { id, placedAt };
}

console.log(JSON.stringify(orderJson("ord_1", new Date("2026-10-01T09:00:00Z"))));
```

TS2322 says the types of `placedAt` are incompatible. A `Date` isn't a primitive or an array, and it has no index signature, so it doesn't fit `{ [key: string]: JsonValue }` either. One gap remains: `NaN` is a `number`, so `JsonValue` can't catch it.

examples.code:
type JsonValue =
  | string
  | number
  | boolean
  | null
  | JsonValue[]
  | { [key: string]: JsonValue };

class Money {
  cents: number;
  currency: string;

  constructor(cents: number, currency: string) {
    this.cents = cents;
    this.currency = currency;
  }

  toJSON(): JsonValue {
    return `${(this.cents / 100).toFixed(2)} ${this.currency}`;
  }
}

function replacer(key: string, value: unknown): unknown {
  return value instanceof Map ? Object.fromEntries(value) : value;
}

const product = {
  sku: "MUG-1",
  price: new Money(1299, "GBP"),
  stock: new Map([
    ["london", 4],
    ["leeds", 0],
  ]),
};

console.log(JSON.stringify(product));
console.log(JSON.stringify(product, replacer));

